import random

@dataclass(frozen=True, slots=True)
class RetryPolicy:
    base_delay: float = 0.5
    max_delay: float = 20.0

    def delay(self, attempt, retry_after, rng):
        jittered = rng.uniform(0.0, min(self.max_delay, self.base_delay * 2**attempt))
        return jittered if retry_after is None else max(jittered, retry_after)

class WorstCase(random.Random):
    def uniform(self, a, b):
        return b            # always the top of the jitter window

p, r = RetryPolicy(), WorstCase()
print(p.delay(0, 2.0, r), p.delay(3, 2.0, r), p.delay(3, None, r), p.delay(10, None, r))
```

